function buildPlan(profile){
  const base=(PLAN[profile.goal]||PLAN.admin).slice();
  const qw=QUICK_WIN[profile.industry];
  if(qw&&!base.some(s=>s[3]===qw[3]))base.unshift(qw);
  return base.map((s,i)=>({position:i,phase:s[0],title:s[1],detail:s[2],prompt_slug:s[3],done_at:null}));
}

