const S={demo:false,user:null,email:"",isPro:false,profile:null,free:FREE_FALLBACK,pro:PRO_FALLBACK,bodies:{},saved:new Set(),uses:[],steps:[],view:"home",filters:{area:"All",tier:"All",q:"",savedOnly:false}};
