const api={
  async sendLink(email){const {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname,shouldCreateUser:true}});if(error)throw error;},
  async load(){
    const uid=S.user.id;
    const [prof,mem,saved,uses,steps]=await Promise.all([
      sb.from("member_profiles").select("*").eq("user_id",uid).maybeSingle(),
      sb.from("members").select("status,current_period_end").eq("user_id",uid).maybeSingle(),
      sb.from("saved_prompts").select("slug"),
      sb.from("prompt_uses").select("slug,hours_saved,created_at").order("created_at",{ascending:false}),
      sb.from("plan_steps").select("*").order("position")]);
    S.profile=prof.data||null;
    const m=mem.data;S.isPro=!!(m&&["active","trialing"].includes(m.status)&&(!m.current_period_end||new Date(m.current_period_end)>new Date()));
    S.saved=new Set((saved.data||[]).map(r=>r.slug));S.uses=uses.data||[];S.steps=steps.data||[];
    if(S.isPro){const b=await sb.from("premium_prompt_bodies").select("slug,prompt");(b.data||[]).forEach(r=>{S.bodies[r.slug]=r.prompt;});}
  },
  async saveProfile(p){const row=Object.assign({},p,{user_id:S.user.id,onboarded_at:new Date().toISOString()});const {data,error}=await sb.from("member_profiles").upsert(row).select().single();if(error)throw error;S.profile=data;},
  async replacePlan(steps){await sb.from("plan_steps").delete().eq("user_id",S.user.id);const rows=steps.map(s=>Object.assign({user_id:S.user.id},s));const {data,error}=await sb.from("plan_steps").insert(rows).select();if(error)throw error;S.steps=(data||[]).sort((a,b)=>a.position-b.position);},
  async toggleStep(step){const done_at=step.done_at?null:new Date().toISOString();const {error}=await sb.from("plan_steps").update({done_at}).eq("id",step.id);if(error)throw error;step.done_at=done_at;},
  async toggleSave(slug){if(S.saved.has(slug)){await sb.from("saved_prompts").delete().eq("slug",slug);S.saved.delete(slug);}else{const {error}=await sb.from("saved_prompts").insert({slug});if(error)throw error;S.saved.add(slug);}},
  async logUse(slug,hours){const {data,error}=await sb.from("prompt_uses").insert({slug,hours_saved:hours}).select().single();if(error)throw error;S.uses.unshift(data);},
  async signOut(){await sb.auth.signOut();}
};
