/* ---------- helpers ---------- */
function allPrompts(){return S.free.map(p=>Object.assign({pro:false},p)).concat(S.pro.map(p=>Object.assign({pro:true},p,S.bodies[p.slug]?{prompt:S.bodies[p.slug]}:{})));}
function bySlug(slug){return allPrompts().find(p=>p.slug===slug);}
function hoursTotal(){return S.uses.reduce((a,u)=>a+Number(u.hours_saved||0),0);}
function firstName(){return (S.profile&&S.profile.first_name)||"";}
function greeting(){const h=new Date().getHours();return h<12?"Morning":h<18?"Afternoon":"Evening";}
function toast(msg){const t=$("toast");t.textContent=msg;t.hidden=false;clearTimeout(toast._t);toast._t=setTimeout(()=>{t.hidden=true;},2600);}
function locked(p){return p.pro&&!p.prompt;}
